class Policy:
    # Track scores and prioritize unsolved/uncertain tasks over solved ones.
    def __init__(self):
        self.scores = {}
        self.visits = {}

    def pick(self, keys, round_index):
        # Filter to tasks we haven't seen as solved (score >= 1.0)
        unsolved = [k for k in keys if self.scores.get(k, 0) < 1.0]
        if not unsolved:
            unsolved = list(keys)

        # Among unsolved, prefer least-visited (exploration) then lowest score
        def priority(k):
            return (self.visits.get(k, 0), self.scores.get(k, 0.0))
        return min(unsolved, key=priority)

    def record(self, task_id, score):
        self.scores[task_id] = score
        self.visits[task_id] = self.visits.get(task_id, 0) + 1
